function findPeakElement(nums) {
  let low = 0;
  let high = nums.length - 1;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (nums[mid] > nums[mid + 1]) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

def find_peak_element(nums):
    low, high = 0, len(nums) - 1
    while low < high:
        mid = (low + high) // 2
        if nums[mid] > nums[mid + 1]:
            high = mid                    # downhill: a peak is at mid or to its left
        else:
            low = mid + 1                 # uphill: a peak is to the right
    return low

int findPeakElement(int[] nums) {
    int low = 0, high = nums.length - 1;
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (nums[mid] > nums[mid + 1]) high = mid;   // downhill: a peak is at mid or to its left
        else low = mid + 1;                          // uphill: a peak is to the right
    }
    return low;
}

